"""Render the assembled book and build a keyboard-accessible facing-page viewer."""
from pathlib import Path
import json,subprocess,html
from PIL import Image, ImageDraw
ROOT=Path(__file__).resolve().parents[1];DOC=ROOT/'docs/publication/whole-book-order-preview'
checks=json.loads((DOC/'CHECKS.json').read_text());pages=json.loads((DOC/'PAGE-MAP.json').read_text())
# Current clean review: approvals remain in their separate archived proofs.
for p in pages:p['changes']=[]
images=DOC/'pages';images.mkdir(exist_ok=True)
subprocess.run(['pdftoppm','-r','110','-jpeg','-jpegopt','quality=85','-cropbox',str(ROOT/checks['pdf']),str(images/'page')],check=True)
for stale in images.glob('page-*.jpg'):
    if int(stale.stem.split('-')[-1])>checks['pdfPages']:stale.unlink()
assert len(list(images.glob('page-*.jpg')))==checks['pdfPages']
for p in pages:p['image']=f"pages/page-{p['pdfPage']:03}.jpg"
pdf='../../../'+checks['pdf']+'?revision='+checks['sha256'][:12]
template=r'''<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The Vegetable Guru · Whole-book order preview</title><style>
@font-face{font-family:Nunito;src:url('/fonts/richer-a-6.woff2');font-weight:100 1000}*{box-sizing:border-box}body{margin:0;background:#d9dfcf;color:#173e2c;font:17px/1.5 Nunito,sans-serif}header,main,footer{max-width:1640px;margin:auto;padding:24px 30px}header{max-width:1120px}h1{font-size:42px;line-height:1.1;margin:8px 0 18px}h2{font-size:25px;margin:0 0 12px}.eyebrow{font-size:13px;font-weight:900;letter-spacing:1px}.intro{max-width:930px}.note{background:#fff8e9;padding:18px 22px;border-left:4px solid #a44007}.note ul{padding-left:22px;margin:8px 0}.note li{margin:6px 0}.small,footer{font-size:14px}a{color:#064d32}.button,button{font:800 16px Nunito;background:#173e2c;color:#fff8e9;border:0;border-radius:5px;padding:10px 15px;text-decoration:none;cursor:pointer}button:disabled{opacity:.4;cursor:default}.toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:12px;padding:16px;background:#fff8e9;border-radius:8px}.toolbar label{font-size:14px;font-weight:800}select,input{font:inherit;color:inherit;padding:8px;border:1px solid #9daa92;background:#fffdf6;border-radius:4px;max-width:100%}select{max-width:430px}input{width:80px}.position{font-size:14px;font-weight:800}.spread{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:20px;align-items:start}.spread figure{margin:0;min-width:0}.page-image{position:relative;display:block}.spread img{display:block;width:100%;box-shadow:0 2px 14px #173e2c22;background:white}.spread figcaption{font-size:14px;margin:9px 2px 18px}.placeholder{aspect-ratio:185/240}.gallery{display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:15px;margin:20px 0}.thumb{background:none;border:0;color:#173e2c;padding:0;min-width:0;font:13px Nunito}.thumb img{width:100%;display:block;margin-bottom:5px}details{margin-top:30px}summary{cursor:pointer;font-weight:900}.links{display:flex;gap:18px;flex-wrap:wrap;margin:15px 0}.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}@media(max-width:750px){header,main,footer{padding:18px 12px}h1{font-size:33px}.spread{gap:4px}.spread figcaption{font-size:11px}.toolbar{padding:12px;gap:8px}select{width:100%}.toolbar .jump{width:100%}.placeholder{display:block}}
</style></head><body><header><div class="eyebrow">THE VEGETABLE GURU · COMPLETE BOOK PREVIEW · 18 OCTOBER 2026</div><h1>The complete book</h1><p class="intro">The complete imperial preview: latest opening copy, the illustrated two-page contents, 44 vegetable guides, 14 Troubles guides, the combined Guides/how-to opener, all approved additional pages and the approved index with updated references. Selected G2 and preferred B5 covers are included.</p><p><a class="button" href="__PDF__" target="_blank">Open the whole-book PDF · __SIZE__ MB</a></p><p class="small">__TOTAL__ interior pages plus four cover leaves: __PDFTOTAL__ PDF pages. Printed page numbers are shown below each preview. The PDF has bookmarks and clickable index references.</p><section class="note"><h2>Latest approved changes</h2><ul><li><strong>The approved Growing Techniques order is integrated at pages 145–165.</strong> Organic growing leads into Nutrient cycles and Crop rotation &amp; planning, followed by practical topics.</li><li><strong>Blank pages 150 and 162 preserve the facing spreads.</strong> Rotation, Beds and paths, compost, cultivation and greenhouse continuation pages face as agreed.</li><li><strong>All approved reader edits are included.</strong> The calendar key, selected growing advice, Troubles clarification, compost, sowing and greenhouse wording are current.</li><li><strong>All 44 vegetables retain their two-page guides and approved headers.</strong> Body type sizes, artwork and original gardening records remain intact.</li><li><strong>Contents and index follow the final order.</strong> Two facing contents pages, four index pages and crop-specific links use refreshed references.</li><li><strong>All earlier approved copy is retained, without review highlights.</strong> Missing publication details remain placeholders.</li></ul><p class="small">__TOTAL__ interior pages; imperial edition. This is a screen preview for checking the complete book.</p></section></header><main id="reader"><div class="toolbar"><button id="previous" type="button">← Previous</button><button id="next" type="button">Next →</button><span class="position" id="position" aria-live="polite"></span><div class="jump"><label for="jump">Jump to</label> <select id="jump"></select></div><form id="go"><label for="folio">Book page</label> <input id="folio" type="number" min="1" max="__TOTAL__" value="1"><button type="submit">Go</button></form></div><p class="small">Use the left and right arrow keys to turn spreads. Select a page image to open that page in the PDF.</p><div class="spread" id="spread" aria-live="polite"></div><details id="overview"><summary>See every page in order</summary><div class="gallery" id="gallery"></div></details><div class="links"><a href="../contents-update/REVIEW.html">Contents on their own</a><a href="index/index.html">Current index</a><a href="README.md">Preview notes</a></div></main><footer>A screen review assembled from saved sources; artwork is reduced for browsing and native text remains sharp in the PDF. All original proofs are preserved. This is not a Bookvault upload file.</footer><script>
const pages=__PAGES__,pdf=__PDFJSON__;let spreadIndex=0;const last=Math.floor(pages.length/2),spread=document.getElementById('spread'),jump=document.getElementById('jump');
const label=p=>p.folio===null?p.label:'Page '+p.folio+' · '+p.label;
const imagePath=p=>p.image+'?revision=__REVISION__';
function show(n,updateHash=true){spreadIndex=Math.max(0,Math.min(last,n));const indices=spreadIndex===0?[-1,0]:[spreadIndex*2-1,spreadIndex*2];spread.replaceChildren();for(const i of indices){const p=pages[i],f=document.createElement('figure');if(!p){f.className='placeholder';f.setAttribute('aria-hidden','true');spread.append(f);continue;}const a=document.createElement('a');a.className='page-image';a.href=pdf+'#page='+p.pdfPage;a.target='_blank';const img=document.createElement('img');img.src=imagePath(p);img.alt=label(p);img.decoding='async';a.append(img);const caption=document.createElement('figcaption');caption.textContent=label(p);f.append(a,caption);spread.append(f);}document.getElementById('previous').disabled=spreadIndex===0;document.getElementById('next').disabled=spreadIndex===last;document.getElementById('position').textContent='Spread '+(spreadIndex+1)+' of '+(last+1);if(updateHash)history.replaceState(null,'','#spread='+spreadIndex);}
function goPdf(i){show(Math.floor((i+1)/2));}
let prevKind='';pages.forEach((p,i)=>{const first=p.folio===null?p.kind==='cover':p.kind==='contents'?p.folio===__CONTENTS__:p.kind==='index'?p.folio===__INDEX__:p.label.endsWith(' — continued')?false:true;if(first&&p.kind!=='blank'){const o=document.createElement('option');o.value=i;o.textContent=label(p);jump.append(o);}});
jump.addEventListener('change',()=>goPdf(Number(jump.value)));document.getElementById('previous').onclick=()=>show(spreadIndex-1);document.getElementById('next').onclick=()=>show(spreadIndex+1);document.getElementById('go').onsubmit=e=>{e.preventDefault();const f=Number(document.getElementById('folio').value);if(f>=1&&f<=__TOTAL__)goPdf(f+1);};document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight'){e.preventDefault();show(spreadIndex+1);}if(e.key==='ArrowLeft'){e.preventDefault();show(spreadIndex-1);}});
document.getElementById('overview').addEventListener('toggle',e=>{const g=document.getElementById('gallery');if(!e.target.open||g.children.length)return;pages.forEach((p,i)=>{const b=document.createElement('button');b.className='thumb';const img=document.createElement('img');img.src=imagePath(p);img.alt=label(p);img.loading='lazy';b.append(img,document.createTextNode(p.folio===null?p.label:String(p.folio)));b.onclick=()=>{goPdf(i);document.getElementById('reader').scrollIntoView({behavior:'smooth'});};g.append(b);});});
const match=location.hash.match(/spread=(\d+)/);show(match?Number(match[1]):0,false);
</script></body></html>'''
if checks.get('finalCopyEditFolios'):
    folios=', '.join(map(str,checks['finalCopyEditFolios']))
    template=template.replace('Latest approved changes','Current changes for review').replace('<ul><li><strong>The approved Growing Techniques order',f'<ul><li><strong>John’s final copy edits are included on page {folios}.</strong> Revised text is ready for review at the existing type size; earlier approved sources remain preserved.</li><li><strong>The approved Growing Techniques order').replace('All earlier approved copy is retained, without review highlights.','Earlier approved pages remain, with the requested copy replacements and no review highlights.')
template=template.replace('__REVISION__',checks['sha256'][:12]).replace('__TOTAL__',str(checks['interiorPages'])).replace('__PDFTOTAL__',str(checks['pdfPages'])).replace('__CONTENTS__',str(next(p['folio'] for p in pages if p['kind']=='contents'))).replace('__INDEX__',str(next(p['folio'] for p in pages if p['kind']=='index'))).replace('__PDF__',html.escape(pdf)).replace('__SIZE__',f"{checks['bytes']/1024**2:.1f}").replace('__PAGES__',json.dumps(pages,ensure_ascii=False).replace('</','<\\/')).replace('__PDFJSON__',json.dumps(pdf))
(DOC/'REVIEW.html').write_text(template)
(DOC/'PAGE-MAP.json').write_text(json.dumps(pages,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'renderedPages':len(pages),'facingViews':len(pages)//2+1,'review':str((DOC/'REVIEW.html').relative_to(ROOT))}))

# Refresh current summary images from this exact PDF, removing obsolete spread labels.
for stale in DOC.glob('spread-*.jpg'):stale.unlink()
by_folio={p['folio']:p for p in pages if p['folio'] is not None}
def contact(name,folios,columns,width=400):
    tiles=[]
    for f in folios:
        p=by_folio[f];im=Image.open(DOC/p['image']).convert('RGB');im.thumbnail((width,round(width*240/185)))
        tile=Image.new('RGB',(width,im.height+26),'#d9dfcf');tile.paste(im,(0,26));ImageDraw.Draw(tile).text((5,6),'Page '+str(f),fill='#173e2c');tiles.append(tile)
    h=max(t.height for t in tiles);canvas=Image.new('RGB',(columns*width,((len(tiles)+columns-1)//columns)*h),'#d9dfcf')
    for i,t in enumerate(tiles):canvas.paste(t,((i%columns)*width,(i//columns)*h))
    canvas.save(DOC/name,quality=90)
for left in [2,4,6,8,10,14,66,82,84,98,100,144,146,148,150,152,154,156,158,160,162,164,166,168]:
    contact(f'spread-{left}-{left+1}.jpg',[left,left+1],2,600)
